# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUVA-YI MİLLİYE\'DEN DÜZENLİ ORDUYA GEÇİŞ VE I. İNÖNÜ ZAFERİ (2.4 &amp; 2.5)</text>\n  <rect x="20" y="45" width="315" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="177" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. Düzenli Orduya Geçiş Süreci (1920)</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Kuva-yı Milliye\'nin Yetersizliği:</tspan> Disiplin</text>\n  <text x="40" y="107" font-size="10.5" fill="#78350f">eksikliği, merkezi otoriteye uymama ve</text>\n  <text x="40" y="122" font-size="10.5" fill="#78350f">düzenli Yunan ordusunu durduramama.</text>\n  <text x="32" y="143" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Kırılma Noktası:</tspan> <tspan font-weight="bold">Gediz Muharebesi</tspan> (24</text>\n  <text x="40" y="158" font-size="10.5" fill="#78350f">Ekim 1920) başarısızlığı sonrası Batı Cephesi</text>\n  <text x="40" y="173" font-size="10.5" fill="#78350f"><tspan font-weight="bold">İsmet Bey</tspan> (Batı) ve <tspan font-weight="bold">Refet Bey</tspan> (Güney)</text>\n  <text x="40" y="188" font-size="10.5" fill="#78350f">komutasında ikiye ayrılarak düzenli ordu kuruldu.</text>\n  <text x="32" y="212" font-size="10.5" font-weight="bold" fill="#b45309">• Çerkez Ethem ve Demirci Mehmet Efe</text>\n  <text x="40" y="227" font-size="10.5" fill="#78350f">ayaklanmaları bastırılarak otorite sağlandı.</text>\n  <rect x="355" y="45" width="325" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. I. İnönü Zaferi (6–10 Ocak 1921) Sonuçları</text>\n  <text x="517" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Kodlama: T - A - L - İ - M  (veya M - İ - L - A - T)</text>\n  <rect x="367" y="98" width="300" height="130" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="377" y="116" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">T — Teşkilat-ı Esasiye Kanunu (20 Ocak 1921):</tspan></text>\n  <text x="387" y="130" font-size="10" fill="#1e3a8a">Yeni Türk devletinin ilk anayasası (Egemenlik milletindir).</text>\n  <text x="377" y="148" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">A — Afganistan ile Dostluk Antlaşması (1 Mart 1921)</tspan></text>\n  <text x="377" y="166" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">L — Londra Konferansı (21 Şubat–12 Mart 1921):</tspan></text>\n  <text x="387" y="180" font-size="10" fill="#1e3a8a">İtilaf Devletleri BMM Hükûmeti\'ni hukuken tanıdı.</text>\n  <text x="377" y="198" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">İ — İstiklâl Marşı\'nın Kabulü (12 Mart 1921)</tspan></text>\n  <text x="377" y="216" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">M — Moskova Antlaşması (16 Mart 1921 - SSCB)</tspan></text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">II. İNÖNÜ ZAFERİ, KÜTAHYA-ESKİŞEHİR MUHAREBELERİ VE MAARİF KONGRESİ</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">II. İnönü Zaferi (23 Mart–1 Nisan 1921)</text>\n  <text x="32" y="92" font-size="10.5" fill="#14532d">• Londra Konferansı\'ndan sonuç alamayan</text>\n  <text x="40" y="107" font-size="10.5" fill="#14532d">Yunan ordusunun saldırısı İsmet Paşa</text>\n  <text x="40" y="122" font-size="10.5" fill="#14532d">komutasındaki düzenli ordu tarafından</text>\n  <text x="40" y="137" font-size="10.5" font-weight="bold" fill="#15803d">ikinci kez İnönü mevzilerinde durduruldu.</text>\n  <rect x="32" y="150" width="296" height="52" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="180" y="168" text-anchor="middle" font-size="10" font-style="italic" fill="#14532d">Mustafa Kemal Paşa\'nın Telgrafı:</text>\n  <text x="180" y="183" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">"Siz orada yalnız düşmanı değil, milletin</text>\n  <text x="180" y="196" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">makûs (kötü) talihini de yendiniz!"</text>\n  <text x="32" y="224" font-size="10" fill="#14532d">• İtalya Anadolu\'dan çekilme sürecini başlattı.</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Kütahya-Eskişehir (10–24 Temmuz 1921)</text>\n  <text x="372" y="92" font-size="10.5" fill="#7f1d1d">• Yunan taarruzu karşısında ordunun</text>\n  <text x="380" y="107" font-size="10.5" fill="#7f1d1d">kuşatılıp yok olmasını önlemek için</text>\n  <text x="380" y="122" font-size="10.5" font-weight="bold" fill="#b91c1c">Mustafa Kemal Paşa\'nın emriyle ordu</text>\n  <text x="380" y="137" font-size="10.5" font-weight="bold" fill="#b91c1c">Sakarya Nehri\'nin doğusuna çekildi.</text>\n  <text x="372" y="158" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Maarif Kongresi (15–21 Temmuz 1921):</tspan></text>\n  <text x="380" y="173" font-size="10" fill="#7f1d1d">Savaşın en sıcak günlerinde Ankara\'da toplandı</text>\n  <text x="380" y="188" font-size="10" font-weight="bold" fill="#991b1b">("Cehaletle savaş, düşmanla savaştan az önemli değildir").</text>\n  <text x="372" y="209" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">5 Ağustos 1921:</tspan> Başkomutanlık Kanunu</text>\n  <text x="372" y="226" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">7–8 Ağustos 1921:</tspan> Tekâlif-i Milliye Emirleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MİLLÎ MÜCADELE\'NİN ASKERÎ, SİVİL VE KADIN KAHRAMANLARI (2.7)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Komutanlar ve Cephe Liderleri</text>\n  <text x="30" y="90" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Mustafa Kemal Paşa:</tspan> Millî</text>\n  <text x="38" y="104" font-size="10" fill="#1e3a8a">Mücadele önderi ve Başkomutan.</text>\n  <text x="30" y="123" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Kâzım Karabekir:</tspan> Doğu Cephesi</text>\n  <text x="38" y="137" font-size="10" fill="#1e3a8a">(15. Kolordu · "Yetimlerin Babası").</text>\n  <text x="30" y="156" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">İsmet İnönü:</tspan> Batı Cephesi</text>\n  <text x="38" y="170" font-size="10" fill="#1e3a8a">komutanı ve Lozan başdelegesi.</text>\n  <text x="30" y="189" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Fevzi Çakmak:</tspan> Genelkurmay</text>\n  <text x="38" y="203" font-size="10" fill="#1e3a8a">Başkanı ve Mareşal.</text>\n  <text x="30" y="222" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Ali Fuat Cebesoy &amp; Refet Bele</tspan></text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Kuva-yı Milliye ve Sivil Önderler</text>\n  <text x="255" y="90" font-size="10" fill="#78350f">• <tspan font-weight="bold">Sütçü İmam &amp; Rıdvan Hoca:</tspan></text>\n  <text x="263" y="104" font-size="10" fill="#78350f">Maraş savunmasının öncüleri.</text>\n  <text x="255" y="123" font-size="10" fill="#78350f">• <tspan font-weight="bold">Şahin Bey &amp; Şehit Kâmil:</tspan></text>\n  <text x="263" y="137" font-size="10" fill="#78350f">Antep savunmasının kahramanları.</text>\n  <text x="255" y="156" font-size="10" fill="#78350f">• <tspan font-weight="bold">Ali Saip (Ursavaş) Bey:</tspan></text>\n  <text x="263" y="170" font-size="10" fill="#78350f">Urfa savunmasını örgütleyen lider.</text>\n  <text x="255" y="189" font-size="10" fill="#78350f">• <tspan font-weight="bold">Mehmet Âkif Ersoy:</tspan> İstiklâl</text>\n  <text x="263" y="203" font-size="10" fill="#78350f">Marşı şairi ve Taceddin Dergâhı.</text>\n  <text x="255" y="222" font-size="10" fill="#78350f">• <tspan font-weight="bold">Yörük Ali Efe &amp; Hasan Tahsin</tspan></text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Kadın Kahramanlarımız</text>\n  <text x="480" y="90" font-size="10" fill="#581c87">• <tspan font-weight="bold">Kara Fatma (Fatma Seher Erden):</tspan></text>\n  <text x="488" y="104" font-size="10" fill="#581c87">Üsteğmen rütbeli müfreze komutanı.</text>\n  <text x="480" y="123" font-size="10" fill="#581c87">• <tspan font-weight="bold">Halide Onbaşı (Edip Adıvar):</tspan></text>\n  <text x="488" y="137" font-size="10" fill="#581c87">Sultanahmet mitingi ve cephe muhabiri.</text>\n  <text x="480" y="156" font-size="10" fill="#581c87">• <tspan font-weight="bold">Şerife Bacı:</tspan> İnebolu–Kastamonu</text>\n  <text x="488" y="170" font-size="10" fill="#581c87">İstiklâl Yolu\'nda cephane şehidi.</text>\n  <text x="480" y="189" font-size="10" fill="#581c87">• <tspan font-weight="bold">Gördesli Makbule &amp; Tayyar</tspan></text>\n  <text x="488" y="203" font-size="10" fill="#581c87"><tspan font-weight="bold">Rahmiye (Osmaniye) &amp; Nezahat Onbaşı</tspan></text>\n  <text x="480" y="222" font-size="10" font-weight="bold" fill="#6b21a8">• Kılavuz Hatice (Pozantı/Adana)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
